"use strict";

const http = require("http");
const https = require("https");
const zlib = require("zlib");
const { URL } = require("url");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

const PAGE_HEADERS = {
  "user-agent": UA,
  accept:
    "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
  "accept-language": "en-US,en;q=0.9",
  "accept-encoding": "gzip, deflate, br",
  "sec-fetch-dest": "document",
  "sec-fetch-mode": "navigate",
  "sec-fetch-site": "none",
  "upgrade-insecure-requests": "1",
};

class Jar {
  constructor() {
    this.map = new Map();
  }
  absorb(headers) {
    const lines = (headers && headers["set-cookie"]) || [];
    for (const line of lines) {
      const pair = String(line).split(";")[0];
      const i = pair.indexOf("=");
      if (i > 0) this.map.set(pair.slice(0, i).trim(), pair.slice(i + 1).trim());
    }
  }
  toString() {
    return [...this.map.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
  }
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function requestOnce(urlStr, jar, headers, timeoutMs) {
  return new Promise((resolve, reject) => {
    let target;
    try {
      target = new URL(urlStr);
    } catch {
      reject(new Error(`Invalid URL: ${urlStr}`));
      return;
    }
    const lib = target.protocol === "http:" ? http : https;
    const merged = { ...PAGE_HEADERS, ...(headers || {}) };
    const cookie = jar ? jar.toString() : "";
    if (cookie) merged.cookie = cookie;
    else delete merged.cookie;

    let settled = false;
    const done = (fn, val) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      fn(val);
    };
    const timer = setTimeout(() => {
      req.destroy(new Error(`Request timed out after ${timeoutMs}ms`));
    }, timeoutMs);

    const req = lib.request(
      target,
      { method: "GET", headers: merged },
      (res) => {
        const chunks = [];
        let stream = res;
        const enc = String(res.headers["content-encoding"] || "").toLowerCase();
        try {
          if (enc === "gzip" || enc === "x-gzip") stream = res.pipe(zlib.createGunzip());
          else if (enc === "deflate") stream = res.pipe(zlib.createInflate());
          else if (enc === "br") stream = res.pipe(zlib.createBrotliDecompress());
        } catch {
          stream = res;
        }
        stream.on("data", (c) => chunks.push(c));
        stream.on("end", () =>
          done(resolve, {
            status: res.statusCode || 0,
            headers: res.headers || {},
            text: Buffer.concat(chunks).toString("utf8"),
          })
        );
        stream.on("error", (e) => done(reject, e));
        res.on("error", (e) => done(reject, e));
      }
    );
    req.on("error", (e) => done(reject, e));
    req.end();
  });
}

async function fetchOnce(url, jar, headers, timeoutMs = 45000) {
  let current = String(url);
  let last = { status: 0, finalUrl: current, text: "" };
  for (let hop = 0; hop <= 5; hop++) {
    const r = await requestOnce(current, jar, headers, timeoutMs);
    if (jar) jar.absorb(r.headers);
    last = { status: r.status, finalUrl: current, text: r.text };
    const location = r.headers && r.headers.location;
    if (
      [301, 302, 303, 307, 308].includes(r.status) &&
      location &&
      hop < 5
    ) {
      current = new URL(location, current).toString();
      continue;
    }
    return last;
  }
  return last;
}

async function fetchPage(url, jar, hasData, attempts = 3) {
  let last = { status: 0, finalUrl: url, text: "" };
  for (let i = 0; i < attempts; i++) {
    try {
      last = await fetchOnce(url, jar);
      if (last.status === 200 && hasData(last.text)) return last;
    } catch {

    }
    if (i < attempts - 1) await sleep(800);
  }
  return last;
}

function unescapeDeep(s) {
  let out = String(s || "");
  for (let i = 0; i < 4; i++) {
    const prev = out;
    out = out
      .split("\\\\").join("\u0001")
      .replace(/\\"/g, '"')
      .replace(/\\u([0-9a-fA-F]{4})/g, (m, h) =>
        String.fromCharCode(parseInt(h, 16))
      )
      .replace(/\\\//g, "/")
      .split("\u0001").join("\\");
    if (out === prev) break;
  }
  return out;
}

function parseBalanced(text, start) {
  let depth = 0;
  let inStr = false;
  let esc = false;
  for (let i = start; i < text.length; i++) {
    const c = text[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === "\\") esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') inStr = true;
    else if (c === "{" || c === "[") depth++;
    else if (c === "}" || c === "]") {
      depth--;
      if (depth === 0) {
        try {
          return { json: JSON.parse(text.slice(start, i + 1)), end: i };
        } catch {
          return null;
        }
      }
    }
  }
  return null;
}

function objectAfter(text, marker, from) {
  const idx = text.indexOf(marker, from || 0);
  if (idx < 0) return null;
  const brace = text.indexOf("{", idx + marker.length);
  if (brace < 0) return null;
  return parseBalanced(text, brace);
}

function numOrNull(v) {
  return typeof v === "number" && Number.isFinite(v) ? v : null;
}

function shapeMediaItem(m) {
  const variants = ((m.video_info && m.video_info.variants) || [])
    .filter((v) => v && v.url)
    .map((v) => {
      const dims = /\/(\d{2,5})x(\d{2,5})\//.exec(v.url);
      return {
        bitrate: numOrNull(v.bitrate),
        contentType: v.content_type || null,
        width: dims ? Number(dims[1]) : null,
        height: dims ? Number(dims[2]) : null,
        url: v.url,
      };
    })
    .sort((a, b) => (b.bitrate || 0) - (a.bitrate || 0));
  return {
    id: m.id_str ? String(m.id_str) : null,
    type: m.type || null,
    image: m.media_url_https || null,
    width: m.original_info ? numOrNull(m.original_info.width) : null,
    height: m.original_info ? numOrNull(m.original_info.height) : null,
    durationMs:
      m.video_info && typeof m.video_info.duration_millis === "number"
        ? m.video_info.duration_millis
        : null,
    videoVariants: variants,
  };
}

function shapeMedia(mediaItems) {
  const media = (mediaItems || []).map(shapeMediaItem);
  let video = null;
  let videoBitrate = -1;
  let image = null;
  for (const item of media) {
    for (const v of item.videoVariants) {
      if (v.contentType === "video/mp4" && (v.bitrate || 0) > videoBitrate) {
        videoBitrate = v.bitrate || 0;
        video = v.url;
      }
    }
    if (!image && item.type === "photo" && item.image) {
      image = item.image.includes("?")
        ? item.image
        : `${item.image}?name=orig`;
    }
  }
  const firstVideo = media.find(
    (m) => m.type === "video" || m.type === "animated_gif"
  );
  return {
    media,
    type: firstVideo ? "video" : media.length ? "photo" : "text",
    thumbnail: firstVideo ? firstVideo.image : null,
    download: { video, image },
  };
}

function extractTweetFromPage(html, id) {
  if (!html || html.length < 1000) return null;
  const text = unescapeDeep(html);
  const hit = objectAfter(text, '"tweet_result_by_rest_id":', 0);
  if (!hit || !hit.json || !hit.json.result) return null;
  const tw = hit.json.result;
  if (tw.__typename !== "Tweet") return null;

  const legacy = tw.legacy || {};
  const details = tw.details || {};
  const counts = tw.counts || {};
  const userRes =
    (tw.core && tw.core.user_results && tw.core.user_results.result) || null;
  const uCore = (userRes && userRes.core) || {};
  const uLegacy = (userRes && userRes.legacy) || {};
  const relCounts = (userRes && userRes.relationship_counts) || {};
  const verification = (userRes && userRes.verification) || {};

  const mediaItems =
    tw.media_entities2 ||
    (legacy.extended_entities && legacy.extended_entities.media) ||
    (legacy.entities && legacy.entities.media) ||
    [];
  const shaped = shapeMedia(mediaItems);

  const createdMs =
    typeof details.created_at_ms === "number"
      ? details.created_at_ms
      : legacy.created_at
        ? Date.parse(legacy.created_at)
        : null;

  return {
    id: String(tw.rest_id || id),
    type: shaped.type,
    text: details.full_text || legacy.full_text || "",
    lang: legacy.lang || null,
    createdAt: createdMs ? new Date(createdMs).toISOString() : null,
    likes: numOrNull(
      counts.favorite_count != null ? counts.favorite_count : legacy.favorite_count
    ),
    retweets: numOrNull(
      counts.retweet_count != null ? counts.retweet_count : legacy.retweet_count
    ),
    replies: numOrNull(
      counts.reply_count != null ? counts.reply_count : legacy.reply_count
    ),
    quotes: numOrNull(
      counts.quote_count != null ? counts.quote_count : legacy.quote_count
    ),
    bookmarks: numOrNull(
      counts.bookmark_count != null
        ? counts.bookmark_count
        : legacy.bookmark_count
    ),
    views:
      tw.views && tw.views.count != null && tw.views.count !== ""
        ? Number(tw.views.count)
        : null,
    author: {
      id: userRes && userRes.rest_id ? String(userRes.rest_id) : null,
      username: uCore.screen_name || uLegacy.screen_name || null,
      fullName: uCore.name || uLegacy.name || null,
      avatar:
        (userRes && userRes.avatar && userRes.avatar.image_url) ||
        uLegacy.profile_image_url_https ||
        null,
      verified:
        typeof verification.is_blue_verified === "boolean"
          ? verification.is_blue_verified
          : typeof uLegacy.verified === "boolean"
            ? uLegacy.verified
            : null,
      verifiedType: verification.verified_type || null,
      followers: numOrNull(relCounts.followers),
    },
    media: shaped.media,
    thumbnail: shaped.thumbnail,
    download: shaped.download,
    url: `https://x.com/i/web/status/${tw.rest_id || id}`,
    source: "page",
  };
}

function syndicationToken(id) {
  return ((Number(id) / 1e15) * Math.PI)
    .toString(36)
    .replace(/(0+|\.)/g, "");
}

function shapeSyndicationTweet(j, id) {
  const mediaItems = Array.isArray(j.mediaDetails) ? j.mediaDetails : [];
  const shaped = shapeMedia(mediaItems);
  const user = j.user || {};
  const viewCount =
    j.video && typeof j.video.viewCount === "number" && j.video.viewCount > 0
      ? j.video.viewCount
      : null;
  return {
    id: String(j.id_str || id),
    type: shaped.type,
    text: j.text || "",
    lang: j.lang || null,
    createdAt: j.created_at || null,
    likes: numOrNull(j.favorite_count),
    retweets: null,
    replies: numOrNull(j.conversation_count),
    quotes: null,
    bookmarks: null,
    views: viewCount,
    author: {
      id: user.id_str ? String(user.id_str) : null,
      username: user.screen_name || null,
      fullName: user.name || null,
      avatar: user.profile_image_url_https || null,
      verified:
        typeof user.is_blue_verified === "boolean"
          ? user.is_blue_verified
          : typeof user.verified === "boolean"
            ? user.verified
            : null,
      verifiedType: user.verified_type || null,
      followers: null,
    },
    media: shaped.media,
    thumbnail: shaped.thumbnail,
    download: shaped.download,
    url: `https://x.com/i/web/status/${j.id_str || id}`,
    source: "syndication",
  };
}

async function fetchSyndication(id, jar) {
  const url =
    `https://cdn.syndication.twimg.com/tweet-result?id=${id}` +
    `&lang=en&token=${syndicationToken(id)}`;
  let lastErr = null;
  for (let i = 0; i < 2; i++) {
    try {
      const r = await fetchOnce(url, jar, { accept: "application/json" });
      if (r.status === 200) {
        let j = null;
        try {
          j = JSON.parse(r.text);
        } catch {

        }
        if (j && j.__typename === "Tweet") return shapeSyndicationTweet(j, id);
        if (j && j.__typename === "TweetTombstone") {
          throw new Error("This post is unavailable (deleted, protected, or age-gated)");
        }
        lastErr = new Error("Syndication feed returned an unreadable response");
      } else if (r.status === 404) {
        throw new Error("Tweet not found — it may be deleted or protected");
      } else {
        lastErr = new Error(`Syndication feed refused the request (HTTP ${r.status})`);
      }
    } catch (e) {
      if (/unavailable|not found/.test(e.message)) throw e;
      lastErr = e;
    }
    if (i < 1) await sleep(800);
  }
  throw lastErr || new Error("Could not fetch this tweet");
}

function parseTweetId(input) {
  const s = String(input || "").trim();
  const m = s.match(
    /(?:twitter\.com|x\.com|vxtwitter\.com|fxtwitter\.com)\/[^/]+\/status(?:es)?\/(\d{5,25})/
  );
  if (m) return m[1];
  const web = s.match(/(?:twitter\.com|x\.com)\/i\/web\/status\/(\d{5,25})/);
  if (web) return web[1];
  if (/^\d{5,25}$/.test(s)) return s;
  return null;
}

async function scrapeTweet(input) {
  const id = parseTweetId(input);
  if (!id) throw new Error("Invalid Twitter/X post URL or ID");
  const jar = new Jar();
  const pageUrl = `https://x.com/i/web/status/${id}`;
  try {
    const page = await fetchPage(
      pageUrl,
      jar,
      (h) => !!extractTweetFromPage(h, id),
      3
    );
    const data = extractTweetFromPage(page.text, id);
    if (data) return data;
  } catch {

  }
  return fetchSyndication(id, jar);
}

function formatDuration(durationMs) {
  if (typeof durationMs !== "number" || !Number.isFinite(durationMs) || durationMs <= 0) {
    return null;
  }
  const totalSeconds = Math.round(durationMs / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${minutes}:${String(seconds).padStart(2, "0")}`;
}

async function fetchSelf(url) {
  if (!url) throw new Error("Tweet URL is required");

  const data = await scrapeTweet(url);

  const videos = [];
  const seenVideoUrls = new Set();
  const images = [];
  const seenImageUrls = new Set();
  let duration = null;

  for (const item of data.media || []) {
    if (duration === null && item.durationMs != null) {
      duration = formatDuration(item.durationMs);
    }
    if (item.type === "video" || item.type === "animated_gif") {
      for (const variant of item.videoVariants || []) {
        if (variant.contentType !== "video/mp4" || !variant.url) continue;
        if (seenVideoUrls.has(variant.url)) continue;
        seenVideoUrls.add(variant.url);
        videos.push({
          quality: variant.height ? `${variant.height}p` : "unknown",
          url: variant.url,
        });
      }
    } else if (item.type === "photo" && item.image) {
      const imageUrl = item.image.includes("?")
        ? item.image
        : `${item.image}?name=orig`;
      if (seenImageUrls.has(imageUrl)) continue;
      seenImageUrls.add(imageUrl);
      images.push({ url: imageUrl });
    }
  }

  videos.sort((a, b) => (parseInt(b.quality) || 0) - (parseInt(a.quality) || 0));

  if (!videos.length && !images.length) {
    throw new Error("No media found via self-scrape");
  }

  const title = data.text && String(data.text).trim() ? String(data.text).trim() : null;

  return {
    success: true,
    source: "X",
    data: {
      type: videos.length ? "video" : images.length ? "photo" : "unknown",
      tweetId: data.id ? String(data.id) : null,
      title,
      duration,
      thumbnail: data.thumbnail || images[0]?.url || null,
      videos,
      images,
      download: { best: videos[0]?.url || images[0]?.url || null },
    },
  };
}

module.exports = fetchSelf;
